  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C06", "C10", "C11", "C21", "C09", "C16"],
  "claims": [
    {
      "claim": "Codeine, the closest morphinan analog with an absolute oral bioavailability record, had F = 80.5% in healthy subjects after oral and intravenous administration, supporting F ≥ 20% for the query hydromorphone, which shares the morphinan scaffold, 4,5-epoxy bridge, N-methyl group, and phenolic C3 substitution.",
      "card_ids": ["C06"]
    },
    {
      "claim": "L2 codeine records show relative oral-vs-intramuscular bioavailability of about 50-55% in smokers and nonsmokers; these are not absolute F values but demonstrate substantial oral absorption and do not contradict F ≥ 20%.",
      "card_ids": ["C27", "C34", "C46", "C57"]
    },
    {
      "claim": "Other opioid analgesics in the evidence set all exceeded the 20% threshold: pentazocine ~0.68-0.70 in cirrhosis (C09, C16, C25, C54), meperidine 0.80-0.87 in cirrhosis (C11, C21, C24, C41, C51, C56, C59), and meptazinol 27.9% in cirrhosis (C10, C36, C55).",
      "card_ids": ["C09", "C16", "C25", "C54", "C11", "C21", "C24", "C41", "C51", "C56", "C59", "C10", "C36", "C55"]
    },
    {
      "claim": "No supplied record provides affirmative evidence of F < 20% for hydromorphone or a close analog; the low-bioavailability L2 record for norethisterone in rats and rabbits (C29) concerns a different steroid and is not transferable to this morphinan query.",
      "card_ids": ["C29"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "associated_nonvoting_records",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C24", "C25", "C26", "C27", "C28", "C31", "C33", "C34", "C36", "C37", "C40", "C41", "C42", "C46", "C49", "C51", "C54", "C55", "C56", "C57", "C58", "C59"]
    },
    {
      "family": "associated_nonvoting_records",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C29", "C30", "C32", "C35", "C38", "C39", "C43", "C44", "C45", "C47", "C48", "C50", "C52", "C53"]
    }
  ],
  "evidence_gaps": [
    "No direct hydromorphone absolute oral bioavailability record is present; the prediction relies on structural transfer from codeine and class-level opioid data.",
    "Codeine differs from hydromorphone at C3 (methoxy vs phenol) and C6 (hydroxy vs ketone), which may alter first-pass metabolism; no matched oral-vs-IV hydromorphone exposure data are supplied.",
    "Several supporting opioid values were measured in cirrhosis patients and may not reflect healthy-subject F, though all remain above 20%.",
    "L2 codeine values are relative to intramuscular administration, not absolute F, so they are context rather than direct endpoint evidence."
  ],
  "decision_summary": "Hydromorphone is predicted high (F ≥ 20%) because the closest morphinan analog codeine has absolute F = 80.5% in healthy subjects, other opioids in the evidence set all exceed 20%, and the physicochemical prior is favorable; L2 records reinforce substantial oral absorption and provide no affirmative evidence of F < 20%, though no direct hydromorphone record is available."
}

